'use strict';
const POS=['Pilier gauche','Talonneur','Pilier droit','Deuxième ligne','Deuxième ligne','Troisième ligne','Troisième ligne','Numéro 8','Demi de mêlée','Demi d’ouverture','Ailier','Centre','Centre','Ailier','Arrière'];
const FAMILIES=[0,1,0,2,2,3,3,3,4,5,6,7,7,6,8];
const TACTICS={equilibre:['Équilibré','Un jeu varié, avec une dépense physique modérée.'],large:['Jeu au large','Passe et vitesse des arrières : gains plus longs, mais fatigue et risque de faute de main accrus, surtout sous la pluie.'],conquete:['Jeu au près','Puissance des avants et conservation. Gains plus courts, moins de fautes de main ; pénaltouche privilégiée.'],occupation:['Occupation','Davantage de coups de pied pour gagner du terrain, en rendant souvent le ballon. Moins de fatigue en attaque ; dépend du pied et du vent.']};
const TRAIN={repos:['Récupération','+30 de condition, aucun progrès technique.'],normal:['Travail collectif','+20 de condition, progression modérée.'],intense:['Haute intensité','+8 de condition, progression renforcée. Risque de blessure.']};
let S=null,view='dashboard',timer=null,modal=null;
try{loadedSaveText=gameStorage.getItem('bdt-v1');const saved=JSON.parse(loadedSaveText);if(saved&&[1,2].includes(saved.version))S=saved;else if(saved)loadSaveFailure='Cette sauvegarde locale utilise une version inconnue. Importez un export compatible.'}catch(e){loadSaveFailure='La sauvegarde locale est illisible. Vous pouvez importer votre dernier export.'}
const $=s=>document.querySelector(s),rand=(a,b)=>Math.floor(Math.random()*(b-a+1))+a,clamp=(n,a,b)=>Math.max(a,Math.min(b,n)),money=n=>new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(n),mean=a=>a.reduce((x,y)=>x+y,0)/(a.length||1);
function save(){if(!S||validatingStartup)return;try{gameStorage.setItem('bdt-v1',JSON.stringify(S));lastSaveError=false}catch(e){lastSaveError=true;toast('Sauvegarde locale impossible. Exportez votre carrière avant de quitter le jeu.')}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3800)}
function makePlayer(ci,i,base){const fam=FAMILIES[i%15];return ensureSkills({id:`p${ci}-${i}-${Date.now()}`,name:FIRST[(ci*3+i*7)%FIRST.length]+' '+LAST[(ci*7+i*3)%LAST.length],pos:POS[i%15],fam,age:rand(20,33),rating:clamp(base+rand(-9,7),50,94),condition:rand(88,100),injury:0,salary:rand(4500,11500)})}
function schedule(){let a=Array.from({length:14},(_,i)=>i),out=[];for(let r=0;r<13;r++){let pairs=[];for(let i=0;i<7;i++){let h=a[i],v=a[13-i];if((r+i)%2)[h,v]=[v,h];pairs.push([h,v])}out.push(pairs);a.splice(1,0,a.pop())}return [...out,...out.map(r=>r.map(([a,b])=>[b,a]))]}
function start(ci){S={version:2,club:ci,season:1,round:0,clubs:CLUBS.map((c,i)=>({id:i,name:c[0],abbr:c[1],color:c[2],base:c[3],cash:c[4]*1e6,goal:c[5],stadium:c[6],points:0,played:0,won:0,drawn:0,lost:0,pf:0,pa:0,bonus:0,form:[],players:Array.from({length:30},(_,j)=>makePlayer(i,j,c[3]))})),schedule:schedule(),lineup:[],reserves:[],tactic:'equilibre',training:'normal',morale:75,trust:70,history:[],news:['Bienvenue au club. Le président vous confie les clés du projet sportif.'],market:[],marketWeek:-1,phase:'league',playoff:null,live:null,lastReport:null,ledger:[],trained:false};setupOpposition();setupEconomy();setupDevelopment();autoLineup();refreshMarket();setupManager();save();view='dashboard';render();toast('Bienvenue au club. Votre saison commence maintenant.')}
function club(){return S.clubs[S.club]}
function player(id){return club().players.find(p=>p.id===id)}
function bestLineup(c){return buildSheet(c).lineup}
function autoLineup(){const sheet=buildSheet(club());S.lineup=sheet.lineup;S.reserves=sheet.bench}
function starters(){return S.lineup.map(player).filter(Boolean)}
function strength(ci){let c=S.clubs[ci];let team=ci===S.club?starters():bestLineup(c).map(id=>c.players.find(p=>p.id===id)).filter(Boolean);let n=mean(team.map(p=>p.rating*(.57+p.condition*.0043)));return n-(15-team.length)*4+(ci===S.club?(S.morale-70)*.08:0)}
function ranked(){return [...S.clubs].sort((a,b)=>b.points-a.points||(b.pf-b.pa)-(a.pf-a.pa)||b.pf-a.pf||a.id-b.id)}
function roundPairs(){if(S.phase==='league')return S.schedule[S.round]||[];return S.playoff?.pairs||[]}
function nextMatch(){return roundPairs().find(p=>p.includes(S.club))}
function badge(ci,size=''){let c=S?S.clubs[ci]:{abbr:CLUBS[ci][1],color:CLUBS[ci][2]};return `<span class="crest ${size}" style="color:${c.color}">${c.abbr}</span>`}
function label(){return S.phase==='league'?`Journée ${S.round+1} / 26`:S.phase==='barrage'?'Barrages':S.phase==='semi'?'Demi-finales':S.phase==='final'?'Finale':'Saison terminée'}
function form(c){return `<span class="form">${c.form.slice(-5).map(f=>`<span class="${f}">${f}</span>`).join('')}</span>`}
function nav(v){if(S.live&&v==='saves'&&!S.live.finished)pauseMatch();if(S.live&&v!=='match'&&v!=='saves'){toast('Terminez le match avant de retourner au club.');return}view=v;render()}
function heading(k,t,desc,action=''){return `<div class="heading"><div><div class="eyebrow">${k}</div><h1>${t}</h1>${desc?`<p>${desc}</p>`:''}</div>${action}</div>`}
function render(){if(!S){renderWelcome();if(modal)$('#app').innerHTML+=modal;return}const c=club(),r=ranked().findIndex(x=>x.id===S.club)+1;$('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="wordmark">CADRAGE<br><span>DÉBORDEMENT.</span></div><div class="edition">RUGBY MANAGER · ÉDITION 16</div><div class="clubbox">${badge(S.club)}<div><strong style="color:white">${c.abbr}</strong><div style="font-size:10px;margin-top:4px">Saison ${S.season} · ${r}e du championnat</div></div></div><nav>${[['dashboard','◈','Bureau du manager'],['team','♙','Effectif & 23'],['tactics','⌘','Préparation'],['plans','▧','Plan de jeu'],['staff','♧','Staff'],['recruitment','⌕','Recrutement'],['match','◉','Centre de match'],['league','▤','Championnat'],['market','⇄','Mercato'],['formation','◇','Formation'],['finance','€','Finances'],['saves','↓','Sauvegardes'],['help','?','Comment jouer']].map(([v,i,t])=>`<button class="nav ${view===v?'active':''}" onclick="nav('${v}')"><i>${i}</i>${t}</button>`).join('')}</nav><div class="sidebottom"><span class="dot"></span> ${lastSaveError?'ÉCHEC DE SAUVEGARDE':'SAUVEGARDE AUTOMATIQUE'}<br>${storageLocationText()}${gameStorage.offline?`<br><button onclick="window.CDOfflineAction('quit')">Enregistrer et quitter</button>`:''}<br><button onclick="resetDialog()">Nouvelle carrière ↗</button></div></aside><main class="main"><header class="topbar"><span>COMPÉTITION <strong style="margin-left:12px">TOP 14</strong></span><span class="saved"><span class="dot"></span> Saison ${S.season} <span style="margin:0 8px">/</span> ${label()}</span></header>${({dashboard,team,tactics,plans:playbookView,staff:staffView,recruitment:recruitmentView,match:matchView,league,market,formation:formationView,finance,saves:savesView,help})[view]()}</main></div>${modal||''}`}
function renderWelcome(){$('#app').innerHTML=`<main class="welcome"><div class="welcomeheader"><div class="wordmark">CADRAGE <span>DÉBORDEMENT.</span></div><span class="seasonmark">RUGBY MANAGER</span></div><div class="intro">${loadSaveFailure?`<div class="notice danger">${loadSaveFailure}</div>`:''}<div class="eyebrow">LE VESTIAIRE VOUS ATTEND</div><h1>Quatorze clubs.<br>Un seul Bouclier.</h1><p>Choisissez votre banc. Construisez votre XV, imposez votre jeu et menez votre club jusqu’au Brennus.</p></div><div class="row"><button onclick="openImportPicker()">Importer une carrière JSON ↑</button></div><div class="row"><h2>Votre carrière commence ici</h2><span class="eyebrow">CHOISISSEZ UN CLUB</span></div><div class="clubs">${CLUBS.map((c,i)=>`<button class="clubchoice" onclick="start(${i})">${badge(i)}<h3>${c[0]}</h3><p>${c[5]} · ${c[4].toFixed(1).replace('.',',')} M€</p><div class="row" style="margin:14px 0 0"><span class="eyebrow">NIVEAU</span><strong>${c[3]} <span class="muted">/ 100</span></strong></div></button>`).join('')}</div><div class="welcomefoot"><span>Clubs réels · Joueurs, évaluations, calendrier et finances fictifs</span><span>Jeu indépendant · Sans affiliation à la LNR</span></div></main>`}
function table(short=false){return `<div class="tablewrap"><table><thead><tr><th>#</th><th>CLUB</th><th>PTS</th><th>J</th>${short?'':'<th>V</th><th>N</th><th>D</th><th>BONUS</th><th>DIFF.</th><th>FORME</th>'}</tr></thead><tbody>${ranked().map((c,i)=>`<tr class="${c.id===S.club?'mine':''}"><td>${i+1}</td><td><span style="display:inline-block;width:5px;height:14px;background:${c.color};margin-right:9px;border-radius:2px"></span>${short?c.abbr:c.name}${i<2?' <small class="muted">•</small>':''}</td><td><strong>${c.points}</strong></td><td>${c.played}</td>${short?'':`<td>${c.won}</td><td>${c.drawn}</td><td>${c.lost}</td><td>${c.bonus}</td><td>${c.pf-c.pa>0?'+':''}${c.pf-c.pa}</td><td>${form(c)}</td>`}</tr>`).join('')}</tbody></table></div>`}
function fixtureCard(){let m=nextMatch();if(!m)return `<div class="card hero"><div class="eyebrow">${label()}</div><h2>${S.phase==='ended'?'Le rideau tombe sur la saison.':'Le championnat continue.'}</h2><p style="color:#b1c8b7">${S.phase==='ended'?S.ending:'Votre équipe ne joue pas à ce tour. Suivez les autres rencontres.'}</p><button class="primary" onclick="${S.phase==='ended'?'nextSeason()':'beginMatch()'}">${S.phase==='ended'?'Lancer la saison suivante':'Simuler ce tour'} →</button></div>`;let [h,a]=m;return `<div class="card hero"><div class="row" style="margin:0"><span class="eyebrow">PROCHAIN RENDEZ-VOUS</span><span class="tag">${S.phase==='league'?'J'+(S.round+1):label()}</span></div><div class="fixture"><div>${badge(h)}<h3>${S.clubs[h].name}</h3></div><div class="vs">VS</div><div>${badge(a)}<h3>${S.clubs[a].name}</h3></div></div><div class="herofoot"><span>${S.phase==='semi'||S.phase==='final'?'Terrain neutre':S.clubs[h].stadium}<br>${h===S.club?'À domicile':'À l’extérieur'}</span><button class="primary" onclick="${view==='match'?'beginMatch()':"nav('match')"}">${view==='match'?'Coup d’envoi →':'Préparer le match ↗'}</button></div></div>`}
function meter(n){return `<div class="meter"><span style="width:${n}%;background:${n<55?'#c8854e':'#5c8969'}"></span></div>`}
function team(){return managerTeamView()}
function dashboard(){return managerOffice()}
function callAcademy(){promoteCover()}
function selectPlayer(i,id){chooseSheet(i,id)}
function tactics(){return heading('LES DÉTAILS FONT LA DIFFÉRENCE','Donnez une identité à votre jeu.','Les choix de préparation sont appliqués lorsque vous lancez le prochain match.')+`<div class="stack"><div class="card"><div class="cardtitle"><h2>01 / Plan d’attaque</h2><span class="tag">APPLIQUÉ AU PROCHAIN MATCH</span></div><div class="options" style="grid-template-columns:repeat(2,1fr)">${Object.entries(TACTICS).map(([k,[t,d]])=>`<button class="option ${S.tactic===k?'selected':''}" onclick="setChoice('tactic','${k}')">${t}<small>${d}</small></button>`).join('')}</div><p class="help">Chaque style utilise les attributs des joueurs sur le terrain. La pluie réduit l’efficacité du jeu au large ; le vent perturbe le jeu au pied. Les plans modifient les attributs utilisés, les gains, les fautes de main et la fatigue. Aucun plan ne garantit la victoire.</p></div>${defencePreparation()}<div class="card"><div class="cardtitle"><h2>03 / Charge d’entraînement</h2><span class="eyebrow">UNE SÉANCE PAR JOURNÉE</span></div><div class="options">${Object.entries(TRAIN).map(([k,[t,d]])=>`<button class="option ${S.training===k?'selected':''}" onclick="setChoice('training','${k}')">${t}<small>${d}</small></button>`).join('')}</div></div>${difficultyPanel()}<div class="card"><h2>L’avis de votre adjoint</h2><p>${mean(starters().map(p=>p.condition))<70?'Votre XV est fatigué. Privilégiez la récupération et donnez du temps de jeu aux remplaçants.':'Le groupe est prêt à travailler. Gardez un œil sur la condition avant de choisir une forte intensité.'}</p><button class="dark" onclick="nav('match')">Aller au centre de match →</button></div></div>`}
function setChoice(k,v){if(S.live){toast('Le match est en cours.');return}S[k]=v;save();render()}
function league(){return heading('LA COURSE AU BRENNUS','Le championnat.','26 journées. Les six premiers jouent les phases finales.')+`<div class="stack"><div class="card"><div class="cardtitle"><h2>Classement général</h2><span class="tag">${S.round} / 26 JOURNÉES</span></div>${table()}<p class="help">1–2 : demi-finales · 3–6 : barrages · 13 : zone de barrage de maintien · 14 : relégation.<br>Départage simplifié : différence de points, puis points marqués. Cette version ne simule pas la Pro D2.</p></div>${S.playoff?`<div class="card"><h2>Phases finales</h2>${S.playoff.log.map(t=>`<div class="news">${t}</div>`).join('')}${S.phase==='ended'?`<div class="notice">${S.ending}</div>`:''}</div>`:''}<div class="card"><h2>Calendrier & résultats</h2>${S.schedule.map((pairs,r)=>{const m=pairs.find(p=>p.includes(S.club));const result=S.history.find(x=>x.round===r&&x.phase==='league'&&x.pair.includes(S.club));return `<div class="row budgetline"><span><span class="eyebrow">J${r+1}</span> &nbsp; ${S.clubs[m[0]].abbr} — ${S.clubs[m[1]].abbr}</span><strong>${result?`${result.score[0]} – ${result.score[1]}`:r===S.round&&S.phase==='league'?'À venir':'—'}</strong></div>`}).join('')}</div></div>`}
function refreshMarket(){S.market=Array.from({length:9},(_,i)=>{let p=makePlayer(99+S.round,i+S.round*2,rand(68,86));p.id='m'+S.season+'-'+S.round+'-'+i;p.condition=100;p.salary=Math.round((p.rating-45)*280);p.price=Math.round((p.rating-50)**2*420/10000)*10000;return p});S.marketWeek=S.round;economyWeek();S.market=[...S.economy.freeAgents,...S.market];S.market.forEach(ensureDevelopment);managerWeek()}
function market(){return transferMarket()}
function signDialog(id){openContract(id,'recruit')}
function sign(id){openContract(id,'recruit')}
function finance(){const wage=club().players.reduce((s,p)=>s+p.salary,0);return heading('LES FONDATIONS DU CLUB','Garder le cap.','Un modèle économique simplifié, avec des montants fictifs.')+`<div class="stats"><div class="card stat"><span class="eyebrow">TRÉSORERIE</span><b>${(club().cash/1e6).toFixed(2)} <small>M€</small></b></div><div class="card stat"><span class="eyebrow">SALAIRES / SEMAINE</span><b>${Math.round(wage/1000)} <small>k€</small></b></div><div class="card stat"><span class="eyebrow">PARTENAIRES / SEMAINE</span><b>160 <small>k€</small></b></div><div class="card stat"><span class="eyebrow">BILLETTERIE / DOMICILE</span><b>300–450 <small>k€</small></b></div></div><div class="grid"><div class="card"><h2>Derniers mouvements</h2>${S.ledger.slice(0,18).map(l=>`<div class="row budgetline"><span>${l.title}</span><b style="color:${l.amount>=0?'#557b55':'#a85e42'}">${l.amount>0?'+':''}${money(l.amount)}</b></div>`).join('')||'<p>Les premiers mouvements seront enregistrés après votre premier match ou recrutement.</p>'}</div><div class="card"><h2>Vos engagements</h2><div class="row"><span>Salaires sur une saison complète (29 journées)</span><strong>${money(totalWages()*29)}</strong></div><div class="row"><span>Salaires restant à verser (estimation)</span><strong>${money(futureWages())}</strong></div><button class="small" onclick="marketTab='contracts';nav('market')">Anticiper les contrats →</button><h2 style="margin-top:25px">Le mot de la direction</h2><p>Chaque journée génère des revenus de partenaires, des charges de salaires et, à domicile, des recettes de billetterie. Une victoire rapporte également une prime de 80 000 €.</p><p>Une trésorerie négative bloque les recrutements et réduit la confiance du président. Un financement de début de saison permet de poursuivre la carrière.</p><div class="notice">Le budget représente une trésorerie de jeu, pas le budget réel du club. Les contrats pluriannuels, prolongations et ventes se gèrent au Mercato. Le salary cap n’est pas simulé.</div></div></div>`}
function help(){return heading('LE CARNET DU MANAGER','À vous de jouer.','Une carrière courte à prendre en main, des choix à chaque journée.')+`<div class="grid"><div class="card help"><h2>Votre première semaine</h2><ol><li>Ouvrez <b>Effectif & 23</b> pour choisir 15 titulaires et 8 remplaçants, dont trois spécialistes de première ligne. La sélection du staff peut vous aider.</li><li>Dans <b>Préparation</b>, choisissez votre tactique et votre charge d’entraînement.</li><li>Renforcez un poste au <b>Mercato</b> si votre trésorerie le permet. Négociez le salaire et la durée, puis confirmez l’accord. L’onglet Contrats permet de prolonger vos joueurs ; l’onglet Ventes permet de les proposer aux autres clubs.</li><li>Lancez votre rencontre au <b>Centre de match</b>. Mettez le match en pause pour ajuster votre stratégie ou remplacer individuellement un joueur. Une pause est automatique à la mi-temps.</li><li>Consultez les résultats, les blessures et les finances avant le prochain rendez-vous.</li></ol><h2>Préparer le prochain adversaire</h2><p>Le Centre de match présente les résultats archivés, une projection des qualités adverses et des conseils argumentés. Adopter le plan règle votre attaque et votre défense principales ; vos consignes par zone restent prioritaires. Comparez vos options par poste, puis composez les 23. La composition adverse et la météo ne sont pas garanties avant le coup d’envoi.</p><p>Après le match, le bilan conserve le plan initial, les plans effectifs par phase et les statistiques réelles. Il ne garantit pas qu’une consigne a causé un résultat : les situations et les échantillons diffèrent.</p><h2>Votre bureau et votre staff</h2><p>Le bureau rassemble vos échéances, les messages du staff et les décisions du club. Dans Effectif & 23, triez les joueurs, comparez deux profils et consultez la couverture des postes. Le Staff peut prendre en charge la charge d’entraînement et la feuille à 23.</p><p>Dans Recrutement, confiez une mission par poste, âge, prime et salaire. Elle coûte 5 000 € et demande deux journées ; les rapports portent sur les agents libres disponibles. Suivez les profils puis négociez avec les contrôles habituels.</p><h2>Le carnet de jeu</h2><p>Dans Plan de jeu, adaptez attaque et défense à quatre zones orientées depuis votre en-but. Préparez les mêlées, touches et renvois au centre : les compromis de conservation, gain et prise de risque agissent dans le moteur. Les consignes sont ajustables en pause pendant une rencontre. Les placements 2D restent schématiques.</p><h2>Les entraîneurs adverses</h2><p>Dans Préparation, choisissez Découverte, Classique ou Expert entre deux matchs. Ce réglage change leurs choix de XV, de tactique et de remplacements, sans bonus d’attribut ni de budget. Le niveau est fixé au coup d’envoi. Les changements tactiques sont consignés dans le journal du match.</p><p>En pause, choisissez votre consigne sur pénalité : selon le contexte, chercher les points ou aller en touche. Les tirs restent soumis à la distance, au buteur et à la météo.</p><h2>Emporter votre carrière</h2><p>Dans Sauvegardes, téléchargez un export JSON et conservez-le sur votre ordinateur. Pour reprendre ailleurs, importez ce fichier puis vérifiez le récapitulatif. La carrière remplacée sera conservée dans une copie de secours locale ; un match importé reprend en pause. La sauvegarde automatique ne synchronise pas vos appareils.</p><h2>La formation</h2><p>Quatre espoirs rejoignent le centre à chaque début de saison. Sans salaire professionnel, ils s’entraînent jusqu’à 21 ans inclus. Une promotion leur donne accès aux matchs et ajoute un salaire de 2 000 € par semaine. Le centre de formation ne simule pas de rencontres de jeunes.</p><h2>Les contrats et transferts</h2><p>Les contrats courent jusqu’à la fin d’une saison. Sans prolongation, le joueur quitte le club au passage à la saison suivante, sans indemnité. Un dernier récapitulatif précède cette décision. Les primes sont payées immédiatement et les salaires à chaque journée, y compris les tours de phases finales simulés sans votre équipe.</p><p>Après mise en vente, les offres arrivent à la prochaine journée si un club dispose des moyens nécessaires. Elles restent valables jusqu’à la journée suivante incluse. Un jeune du centre de formation est vendable à partir de 20 ans ; une nouvelle recrue attend trois journées avant de pouvoir être revendue. Les autres clubs renouvellent automatiquement leurs propres contrats.</p><h2>Suivre le match en 2D</h2><p>Le terrain entier et le commentaire surligné représentent la même action. Les actions d’une séquence sont montrées dans l’ordre : essai, renvoi, réception, par exemple. Le score et le chronomètre suivent cette lecture. Les placements restent schématiques.</p><p>Réglez le rythme sur Posé, Normal ou Rapide. Les options Essai et Carton mettent le match en pause après la séquence concernée ; elles sont conservées sur ce navigateur. Une pause manuelle rejoint la fin de la séquence déjà calculée, sans jouer de minute supplémentaire. Le bouton d’avance rapide passe les animations et respecte les pauses choisies.</p><p>Cliquez sur un joueur pour mettre en pause et ouvrir sa fiche. Pour vos joueurs, les remplaçants autorisés au poste sont proposés directement. Le filtre Temps forts conserve toujours l’action représentée sur le terrain. Sur petit écran, les commentaires passent sous le terrain. Les actions des anciennes sauvegardes sans position enregistrée ne sont pas reconstruites ; les suivantes sont synchronisées.</p><h2>Vos consignes changent le match</h2><p>Le plan d’attaque choisit les qualités mobilisées et influence les gains, les fautes de main, le recours au pied et la fatigue. Le jeu au près s’appuie sur la puissance des avants ; le jeu au large sur la passe et la vitesse des arrières. L’occupation privilégie le pied dans votre camp, moins souvent près de l’en-but adverse.</p><p>La défense se règle séparément. La montée agressive freine les premières avancées et provoque plus d’erreurs, avec davantage de fatigue et de risque de pénalité. Si elle est battue, les gains adverses peuvent être plus grands. La glissée prudente cède davantage de petites avancées pour limiter les grands gains. Les mêmes effets s’appliquent aux deux équipes.</p><p>Réglez les deux plans dans Préparation puis ajustez-les en pause. Le terrain montre les placements correspondant à l’action affichée. À la mi-temps, le staff s’appuie sur les progressions, les fautes de main, la discipline et la fraîcheur pour proposer des ajustements. Les rencontres déjà commencées sous un ancien moteur conservent leurs règles jusqu’au coup de sifflet final.</p><h2>Avantage et fin de période</h2><p>Sur certaines fautes, l’arbitre laisse un avantage. Sans bénéfice suffisant, le jeu revient à la sanction initiale. Après 40 ou 80 minutes, le chronomètre affiche le temps supplémentaire et le jeu peut continuer jusqu’à un arrêt autorisé, notamment pour terminer une pénaltouche ou une transformation. Chaque mi-temps conserve ses quarante minutes de jeu.</p><h2>Les reprises du jeu</h2><p>Un en-avant ou une passe en avant donne une mêlée à l’adversaire. Une sortie en touche donne normalement le lancer à l’adversaire ; la pénaltouche et un 50:22 régulier conservent le lancer. La touche directe dépend de la position dans les 22 et de la manière dont le ballon y est entré.</p><p>Après des points, l’équipe qui les a encaissés effectue le renvoi au centre. Après une pénalité manquée, le ballon peut rester jouable, sortir en touche ou devenir mort pour un renvoi aux 22. Un attaquant tenu dans l’en-but sans aplatir entraîne un renvoi sur la ligne d’essai. Le journal précise ces causes.</p><h2>Les règles du championnat</h2><p>Victoire : 4 points. Nul : 2 points. Bonus offensif : au moins 3 essais de plus que l’adversaire. Bonus défensif : défaite de 5 points ou moins.</p><p>Après 26 journées : 3e contre 6e et 4e contre 5e en barrages ; les vainqueurs affrontent les deux premiers en demi-finales, puis finale. Les égalités en phase finale sont départagées par une prolongation simplifiée.</p></div><div class="card help"><h2>Ce qui fait la différence</h2><p><b>Les remplacements.</b> Le groupe reste limité aux 23 joueurs désignés avant le match. Les sortants restent disponibles : quatre retours tactiques sont autorisés, indépendamment des premières entrées du banc. Le remplacement d’un exclu après vingt minutes ne consomme pas ce quota. Ce cadre des changements est fixé à l’édition professionnelle française 2025–2026 pour toute la carrière fictive. La condition diminue pendant la rencontre ; une meilleure endurance ralentit la fatigue.</p><p><b>Les qualités au poste.</b> Mêlée, touche, plaquage, vitesse, passe, pied, but, mental, discipline, endurance et puissance interviennent dans les phases de jeu.</p><p><b>Le développement.</b> Les jeunes progressent grâce aux entraînements et aux minutes effectivement disputées. Le potentiel fixe une limite ; les gains sont graduels. Le déclin commence plus tôt chez les arrières dans cette simulation. Les retraites ont lieu à l’intersaison, à l’âge annoncé sur la fiche.</p><p><b>Le match.</b> La possession, le territoire et la conquête évoluent à chaque séquence. Les pénalités et cartons jaunes ont un effet réel. Les tirs dépendent du buteur présent sur le terrain. Le même moteur simule les autres clubs. Les statistiques expliquent les tendances, sans garantir un résultat.</p><div class="notice">Jeu indépendant. Clubs réels ; joueurs, notes, budgets, résultats et calendrier fictifs. Simulation simplifiée : pas de blessures en cours de match, de protocole commotion ni de carton rouge direct. Après un second jaune, le joueur reste exclu ; un autre joueur peut entrer après vingt minutes de jeu. À la prochaine mêlée après une exclusion de première ligne, le staff fait entrer un spécialiste et désigne un joueur à sortir. Sans spécialiste disponible, les mêlées ne sont plus disputées, avec la réduction supplémentaire d’effectif prévue. Les remplacements médicaux restent à implémenter. Les anciennes rencontres en cours conservent leurs règles jusqu’à leur fin. Compétitions européennes, Pro D2, JIFF et sélections internationales non simulés. Sauvegarde automatique sur ce navigateur, sans synchronisation entre appareils.</div><p><a href="https://top14.lnr.fr/clubs" target="_blank" rel="noopener">Clubs : site officiel LNR ↗</a><br><a href="https://top14.lnr.fr/actualite/comment-se-deroule-une-saison-de-top-14" target="_blank" rel="noopener">Format du championnat : LNR ↗</a></p></div></div>`}
function news(s){S.news.unshift(s);S.news=S.news.slice(0,20);managerMessage(s,'','club','dashboard')}
function trainWeek(){if(S.trained)return;applyStaffPreparation();S.trained=true;for(let c of S.clubs){const mode=c.id===S.club?S.training:'normal';for(let p of c.players){ensureDevelopment(p);if(p.injury){p.injury--;p.condition=clamp(p.condition+15,0,100);continue}p.condition=clamp(p.condition+(mode==='repos'?30:mode==='normal'?20:8),20,100);developmentTraining(p,mode);if(mode==='intense'&&Math.random()<.018){p.injury=rand(1,3);if(c.id===S.club)news(`${p.name} s’est blessé à l’entraînement : indisponible ${p.injury} semaine(s).`)}}}for(let p of S.development.academy)developmentTraining(p,'normal');repairSheet();}
function matchView(){return rugbyMatchView()}
function beginMatch(){rugbyBegin()}
function tacticalBonus(){return 0}
function startTimer(){clearInterval(timer);timer=setInterval(()=>{if(!S?.live||!presentationPending(S.live)&&(S.live.finished||S.live.paused)){clearInterval(timer);return}rugbyTick()},MATCH_TEMPOS[matchTempo])}
function tick(){rugbyTick()}
function fastForward(){rugbyFast()}
function halfTactic(k){setLiveTactic(k)}
function resumeMatch(){continueMatch()}
function useBench(){rugbyUseBench()}
function simulate(pair){return rugbySimulate(pair)}
function record(r){updateOppositionMorale(r);S.history.push({...r,round:S.round,phase:S.phase});if(S.phase!=='league')return;let [a,b]=r.pair.map(i=>S.clubs[i]),[x,y]=r.score;for(let i=0;i<2;i++){let c=[a,b][i],sc=r.score[i],opp=r.score[1-i],bo=r.tries[i]-r.tries[1-i]>=3?1:0,bd=sc<opp&&opp-sc<=5?1:0;c.played++;c.pf+=sc;c.pa+=opp;c.bonus+=bo+bd;c.points+=(sc>opp?4:sc===opp?2:0)+bo+bd;if(sc>opp)c.won++;else if(sc<opp)c.lost++;else c.drawn++;c.form.push(sc>opp?'V':sc===opp?'N':'D')}}
function financeWeek(m,won){let wage=club().players.reduce((s,p)=>s+p.salary,0);let ticket=m?.[0]===S.club?rand(300,450)*1000:0;let entries=[{title:label()+' · Partenaires',amount:160000},{title:label()+' · Salaires',amount:-wage}];if(ticket)entries.push({title:label()+' · Billetterie',amount:ticket});if(won)entries.push({title:label()+' · Prime de victoire',amount:80000});entries.forEach(e=>club().cash+=e.amount);S.ledger.unshift(...entries);S.ledger=S.ledger.slice(0,100);if(club().cash<0){S.trust=clamp(S.trust-5,0,100);news('La trésorerie est négative. Le président demande de réduire les dépenses.')}}
function finishRound(){if(S.phase==='ended'||(S.live&&!S.live.finished))return;clearInterval(timer);captureReport();const pairs=roundPairs(),m=nextMatch(),results=pairs.map(p=>S.live&&p.includes(S.club)?{pair:p,score:S.live.score,tries:S.live.tries,stats:S.live.stats,weather:S.live.weather}:simulate(p));results.forEach(record);let own=results.find(r=>r.pair.includes(S.club)),won=false;if(own){let idx=own.pair.indexOf(S.club),d=own.score[idx]-own.score[1-idx];won=d>0;S.morale=clamp(S.morale+(d>0?6:d<0?-5:1),25,98);S.trust=clamp(S.trust+(d>0?3:d<0?-2:0),0,100);news(`${d>0?'Victoire':d<0?'Défaite':'Match nul'} : ${S.clubs[own.pair[0]].abbr} ${own.score[0]} – ${own.score[1]} ${S.clubs[own.pair[1]].abbr}.`);}financeWeek(m,won);S.live=null;S.trained=false;if(S.phase==='league'){S.round++;if(S.round===26){let r=ranked();S.playoff={seeds:r.slice(0,6).map(c=>c.id),pairs:[[r[2].id,r[5].id],[r[3].id,r[4].id]],log:[]};S.phase='barrage';let pos=r.findIndex(c=>c.id===S.club)+1;news(`Saison régulière terminée : ${pos}e place. ${pos<=6?'Le Brennus reste à portée.':pos===14?'Vous terminez en zone de relégation.':pos===13?'Vous terminez en zone de barrage de maintien.':'Le travail continue la saison prochaine.'}`)}}else{results.forEach(r=>S.playoff.log.push(`${label()} : ${S.clubs[r.pair[0]].abbr} ${r.score[0]} – ${r.score[1]} ${S.clubs[r.pair[1]].abbr}`));const winners=results.map(r=>r.pair[r.score[0]>r.score[1]?0:1]);if(S.phase==='barrage'){S.phase='semi';S.playoff.pairs=[[S.playoff.seeds[0],winners[1]],[S.playoff.seeds[1],winners[0]]]}else if(S.phase==='semi'){S.phase='final';S.playoff.pairs=[[winners[0],winners[1]]]}else{S.phase='ended';S.playoff.pairs=[];S.ending=`${S.clubs[winners[0]].name} soulève le Bouclier de Brennus !`;news(S.ending);if(winners[0]===S.club){club().cash+=1000000;S.ledger.unshift({title:'Prime de champion',amount:1000000})}}}refreshMarket();repairSheet();view='dashboard';save();render()}
function advanceSeason(){if(S.phase!=='ended'||S.live)return;rollDevelopmentYear();settleContracts();S.season++;S.round=0;S.phase='league';S.schedule=schedule();S.history=[];S.playoff=null;S.lastReport=null;S.ending=null;S.trained=false;S.clubs.forEach(c=>{c.points=c.played=c.won=c.drawn=c.lost=c.pf=c.pa=c.bonus=0;c.form=[];c.morale=75;c.players.forEach(p=>{p.condition=100;p.injury=0;p.managerLoad={minutes:0,streak:0}})});club().cash+=2500000;S.ledger.unshift({title:'Financement de début de saison',amount:2500000});news(`Saison ${S.season} : nouveau départ. La direction apporte 2,5 M€. Clubs conservés dans cette version, sans montée ni descente.`);S.morale=75;beginDevelopmentSeason();autoLineup();if(sheetErrors().length)promoteCover();refreshMarket();modal=null;save();render()}
function resetDialog(){modal=`<div class="modalback"><section class="modal" role="dialog" aria-modal="true" aria-label="Nouvelle carrière"><h2>Changer de banc ?</h2><p>Votre carrière actuelle sera remplacée. Cette action efface votre progression sur ce navigateur.</p><div class="row"><button onclick="closeModal()">Garder ma carrière</button><button class="primary" onclick="resetGame()">Nouvelle carrière</button></div></section></div>`;render()}
function resetGame(){clearInterval(timer);S=null;modal=null;gameStorage.removeItem('bdt-v1');render()}
function closeModal(){modal=null;render()}
